package androidx.constraintlayout.widget;public class ConstraintLayout extends android.view.ViewGroup {public static class LayoutParams extends android.view.ViewGroup.LayoutParams {public int leftToLeft=-1,leftToRight=-1,rightToLeft=-1,rightToRight=-1,startToStart=-1,startToEnd=-1,endToStart=-1,endToEnd=-1,topToTop=-1,topToBottom=-1,bottomToTop=-1,bottomToBottom=-1,leftMargin,rightMargin,topMargin,bottomMargin;public float horizontalBias=.5f,verticalBias=.5f;private int start=Integer.MIN_VALUE,end=Integer.MIN_VALUE;public LayoutParams(int w,int h){super(w,h);}public boolean isMarginRelative(){return start!=Integer.MIN_VALUE||end!=Integer.MIN_VALUE;}public int getMarginStart(){return start;}public int getMarginEnd(){return end;}public void setMarginStart(int s){start=s;}public void setMarginEnd(int e){end=e;}}}